with enriched as (select *, row_number() over (partition by customer_id order by balance desc, id) as row_seq, avg(balance) over (partition by account_type, customer_id) as account_type_avg_balance from accounts) select date_trunc('week', opened_date) as week_start, date_trunc('month', opened_date) as activity_month, sum(account_type_avg_balance) filter (where status = 'CLOSED') as closed_total_account_type_avg_balance, max(row_seq) as max_row_seq, round(sum(account_type_avg_balance) / nullif(count(case when status = 'FROZEN' then 1 end), 0), 2) as account_type_avg_balance_per_frozen, approx_percentile(account_type_avg_balance, 0.5) as account_type_avg_balance_p50, round(sum(account_type_avg_balance) / nullif(count(case when status = 'OPEN' then 1 end), 0), 2) as account_type_avg_balance_per_open, round(avg(row_seq), 2) as avg_row_seq, rank() over (partition by date_trunc('week', opened_date) order by round(avg(row_seq), 2) desc) as avg_row_seq_rank from enriched group by date_trunc('week', opened_date), date_trunc('month', opened_date) having round(sum(account_type_avg_balance) / nullif(count(case when status = 'OPEN' then 1 end), 0), 2) < 0;
